"""Create simple dict to simulate api data."""
def new_sleep_summary(
    timezone: Any,
    model: Any,
    startdate: Any,
    enddate: Any,
    date: Any,
    modified: Any,
    data: Any
) -> object {
    return {
        "timezone": timezone,
        "model": model,
        "startdate": startdate,
        "enddate": enddate,
        "date": date,
        "modified": modified,
        "data": data
    };
}

test_blocks:
test "t0" {
    assert (
        new_sleep_summary(
            "America/Los_Angeles",
            "modern",
            "2021-09-06",
            "2021-09-06",
            "2021-09-06",
            "2021-09-06T00:00:00.000Z",
            {"level": "full", "seconds": 86400, "summary": "Restless"}
        )
        == {
            "timezone": "America/Los_Angeles",
            "model": "modern",
            "startdate": "2021-09-06",
            "enddate": "2021-09-06",
            "date": "2021-09-06",
            "modified": "2021-09-06T00:00:00.000Z",
            "data": {"level": "full", "seconds": 86400, "summary": "Restless"}
        }
    );;
}

test "t1" {
    assert (
        new_sleep_summary(
            "America/New_York",
            "OnePlus7t",
            "2020-01-01",
            "2020-01-02",
            "2020-01-03",
            "2020-01-04",
            {"a": 1, "b": 2}
        )
        == {
            "timezone": "America/New_York",
            "model": "OnePlus7t",
            "startdate": "2020-01-01",
            "enddate": "2020-01-02",
            "date": "2020-01-03",
            "modified": "2020-01-04",
            "data": {"a": 1, "b": 2}
        }
    );;
}

test "t2" {
    assert (
        new_sleep_summary(
            "America/Los_Angeles",
            "ASLEEP",
            "2017-07-04T00:00:00",
            "2017-07-05T00:00:00",
            "2017-07-04T01:00:00-07:00",
            "2017-07-05T13:05:10.724904",
            {
                "bedtime_start": "2017-07-04T00:00:00",
                "bedtime_end": "2017-07-04T00:59:00"
            }
        )
        == {
            "timezone": "America/Los_Angeles",
            "model": "ASLEEP",
            "startdate": "2017-07-04T00:00:00",
            "enddate": "2017-07-05T00:00:00",
            "date": "2017-07-04T01:00:00-07:00",
            "modified": "2017-07-05T13:05:10.724904",
            "data": {
                "bedtime_start": "2017-07-04T00:00:00",
                "bedtime_end": "2017-07-04T00:59:00"
            }
        }
    );;
}

test "t3" {
    assert (
        new_sleep_summary(
            "timezone", "model", "startdate", "enddate", "date", "modified", "data"
        )
        == {
            "timezone": "timezone",
            "model": "model",
            "startdate": "startdate",
            "enddate": "enddate",
            "date": "date",
            "modified": "modified",
            "data": "data"
        }
    );;
}

test "t4" {
    assert (
        new_sleep_summary(1, 2, 3, 4, 5, 6, 7)
        == {
            "timezone": 1,
            "model": 2,
            "startdate": 3,
            "enddate": 4,
            "date": 5,
            "modified": 6,
            "data": 7
        }
    );;
}

